window.SB_FEED_BODY=window.SB_FEED_BODY||{},Object.assign(window.SB_FEED_BODY,{"wh-heterogeneous":{src:"concept:66:words:13:hook",route:"#/word/heterogeneous",cta:"Open the word card",title:"Remember it · heterogeneous",body:"HETEROgenEOUS: remember EOUS not IOUS — DIFFERENT GENES make a mix that'sEOUS-ly diverse."},"wo-heterogeneous":{src:"lore:heterogeneous:0",route:"#/word/heterogeneous",cta:"Open the word card",title:"Where it comes from · heterogeneous",body:"Greek heteros = different + genos = kind"},"wd-genus":{src:"concept:66:words:14:def",route:"#/word/genus",cta:"Open the word card",title:"genus",roman:"JEE-nuhs",body:"a general kind of something",clip:1},"wx-genus":{src:"concept:66:words:14:ex",route:"#/word/genus",cta:"Open the word card",title:"In a sentence · genus",body:"ignore the genus communism",clip:1},"wh-genus":{src:"concept:66:words:14:hook",route:"#/word/genus",cta:"Open the word card",title:"Remember it · genus",body:"GENUS and GENIUS are cousins — both start GEN, but genus is shorter, simpler: G-E-N-U-S."},"wd-genre":{src:"concept:66:words:15:def",route:"#/word/genre",cta:"Open the word card",title:"genre",roman:"zh-AH-n-r-uh",body:"a class of artistic endeavor having a particular form",clip:1},"wx-genre":{src:"concept:66:words:15:ex",route:"#/word/genre",cta:"Open the word card",title:"In a sentence · genre",body:"Her favorite genre of music is jazz, but she also loves reading mysteries and watching science fiction films.",clip:1},"wh-genre":{src:"concept:66:words:15:hook",route:"#/word/genre",cta:"Open the word card",title:"Remember it · genre",body:"GENRE sounds fancy and French — keep the silent 'e' at the end like a French café."},"wo-genre":{src:"lore:genre:0",route:"#/word/genre",cta:"Open the word card",title:"Where it comes from · genre",body:"French genre=kind/type, from Latin genus=kind"},"wd-congenital":{src:"concept:66:words:16:def",route:"#/word/congenital",cta:"Open the word card",title:"congenital",roman:"kuh-NJEH-nuh-tuhl",body:"present at birth but not necessarily hereditary; acquired during fetal development",clip:1},"wx-congenital":{src:"concept:66:words:16:ex",route:"#/word/congenital",cta:"Open the word card",title:"In a sentence · congenital",body:"The doctor explained that the infant's heart condition was congenital and had been present since before birth.",clip:1},"wh-congenital":{src:"concept:66:words:16:hook",route:"#/word/congenital",cta:"Open the word card",title:"Remember it · congenital",body:"CONGENITAL conditions are born with you — GENIT-al roots say 'at birth.'"},"wo-congenital":{src:"lore:congenital:0",route:"#/word/congenital",cta:"Open the word card",title:"Where it comes from · congenital",body:"Latin congenitus = born together, con- + genitus = born"},"wd-indigenous":{src:"concept:66:words:17:def",route:"#/word/indigenous",cta:"Open the word card",title:"indigenous",roman:"ih-NDIH-juh-nuhs",body:"originating where it is found",clip:1},"wx-indigenous":{src:"concept:66:words:17:ex",route:"#/word/indigenous",cta:"Open the word card",title:"In a sentence · indigenous",body:"Kangaroos are indigenous to Australia and live nowhere else in the wild.",clip:1},"wh-indigenous":{src:"concept:66:words:17:hook",route:"#/word/indigenous",cta:"Open the word card",title:"Remember it · indigenous",body:"INDIGENOUS has GEN in the middle — indigenous people GENerated the original culture of a place."},"wo-indigenous":{src:"lore:indigenous:0",route:"#/word/indigenous",cta:"Open the word card",title:"Where it comes from · indigenous",body:"Latin indigena = born within"},"li-u64":{src:"concept:67:concept",route:"#/stop/u64",cta:"Open this stop",title:"dem / demo (people)",body:"Greek demos = people. This root creates political and epidemiological vocabulary. Any word about how people govern themselves or how diseases move through populations uses dem-."},"lc-u64-0":{src:"concept:67:cards:0",route:"#/stop/u64",cta:"Open this stop",title:"dem / demo (people) · The Root",body:"Greek demos = people. Democracy (demos + kratos = rule) = rule by the people. Epidemic (epi- = upon + demos) = disease upon the people. Endemic (en- = within) = disease within the people (a specific region). Pandemic (pan- = all) = disease across all peoples worldwide."},"lc-u64-1":{src:"concept:67:cards:1",route:"#/stop/u64",cta:"Open this stop",title:"dem / demo (people) · Democratic Vocabulary",body:"Democracy = the people rule. Demagogue = demos + agogos (leader) = one who leads the people through emotion and manipulation rather than reason. Demotic = of or for ordinary people. Demographics = demos + graphein = writing/data about the people."},"lc-u64-2":{src:"concept:67:cards:2",route:"#/stop/u64",cta:"Open this stop",title:"dem / demo (people) · Epidemic vs Endemic vs Pandemic",body:"Endemic (en- = within) = normally present within a specific population/area (malaria is endemic in some tropical regions). Epidemic (epi- = upon) = an outbreak spreading upon a population. Pandemic (pan- = all) = an epidemic that has spread to all (or most) peoples worldwide."},"lc-u64-3":{src:"concept:67:cards:3",route:"#/stop/u64",cta:"Open this stop",title:"dem / demo (people) · Demiurge — the Craftsman God",body:'Demiurge (demi = people + urgos = worker) = "the craftsman of the people" = in Platonic philosophy, the force that creates the material world. A rare but high-value bee word that combines demos with ergon (work) — Greek compound vocabulary at its most sophisticated.'},"lc-u64-4":{src:"concept:67:cards:4",route:"#/stop/u64",cta:"Open this stop",title:"dem / demo (people) · Spelling dem- Words",body:"Democracy = D-E-M-O-C-R-A-C-Y (not -cracy with a k). Demagogue = D-E-M-A-G-O-G-U-E (-gogue not -gog — the French -ue ending). Epidemic = E-P-I-D-E-M-I-C (epi- + dem- + -ic). Demographics = D-E-M-O-G-R-A-P-H-I-C-S (-ph- Greek signal in -graphics)."},"uq-u64-3":{src:"unit:u64:qs:3",route:"#/stop/u64",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁: DEMO the CRAZY idea that one person rules — demos + kratos, people power!” — which word is this hook about?",opts:["democracy","demagogue","epidemic","endemic"],after:"From “dem / demo (people)”."}},"wd-democracy":{src:"concept:67:words:0:def",route:"#/word/democracy",cta:"Open the word card",title:"democracy",roman:"dih-MAH-kruh-see",body:"the political orientation of those who favor government by the people or by their elected representatives",clip:1},"wx-democracy":{src:"concept:67:words:0:ex",route:"#/word/democracy",cta:"Open the word card",title:"In a sentence · democracy",body:"Students in the civics class debated whether a true democracy could survive when large portions of eligible voters chose not to participate in elections.",clip:1},"wh-democracy":{src:"concept:67:words:0:hook",route:"#/word/democracy",cta:"Open the word card",title:"Remember it · democracy",body:"DEMOCRACY: DEMO the CRAZY idea that one person rules — demos + kratos, people power!"},"wo-democracy":{src:"lore:democracy:0",route:"#/word/democracy",cta:"Open the word card",title:"Where it comes from · democracy",body:"Greek demos = people + kratos = rule/power"},"wd-endemic":{src:"concept:67:words:3:def",route:"#/word/endemic",cta:"Open the word card",title:"endemic",roman:"eh-NDEH-mihk",body:"a disease that is constantly present to a greater or lesser degree in people of a certain class or in people living in a particular location",clip:1},"wx-endemic":{src:"concept:67:words:3:ex",route:"#/word/endemic",cta:"Open the word card",title:"In a sentence · endemic",body:"it is an endemic found only this island",clip:1},"wh-endemic":{src:"concept:67:words:3:hook",route:"#/word/endemic",cta:"Open the word card",title:"Remember it · endemic",body:"Endemic means IN the DEMO (people) of one place — en-DEM-ic, like a built-in local disease."},"wd-demographics":{src:"concept:67:words:5:def",route:"#/word/demographics",cta:"Open the word card",title:"demographics",roman:"deh-muh-GRA-fihks",body:"statistical data characterizing human populations broken down by factors such as age, sex, or income",clip:1},"wx-demographics":{src:"concept:67:words:5:ex",route:"#/word/demographics",cta:"Open the word card",title:"In a sentence · demographics",body:"The marketing team studied the demographics of the city to decide which neighborhoods would best receive their new product.",clip:1},"wh-demographics":{src:"concept:67:words:5:hook",route:"#/word/demographics",cta:"Open the word card",title:"Remember it · demographics",body:"DEMOgraphics studies the DEMO — the people of a place"},"wo-demographics":{src:"lore:demographics:0",route:"#/word/demographics",cta:"Open the word card",title:"Where it comes from · demographics",body:"Greek demos = people + graphein = to write"},"wd-demography":{src:"concept:67:words:6:def",route:"#/word/demography",cta:"Open the word card",title:"demography",roman:"dih-MAH-gruh-fee",body:"the branch of sociology that studies the characteristics of human populations",clip:1},"wx-demography":{src:"concept:67:words:6:ex",route:"#/word/demography",cta:"Open the word card",title:"In a sentence · demography",body:"Studying demography helped the students understand why some countries have aging populations while others are very young.",clip:1},"wh-demography":{src:"concept:67:words:6:hook",route:"#/word/demography",cta:"Open the word card",title:"Remember it · demography",body:"DemoGRAPHy writes (GRAPHS) the story of the people — keep the PH."},"wd-demotic":{src:"concept:67:words:7:def",route:"#/word/demotic",cta:"Open the word card",title:"demotic",roman:"dih-MAH-tik",body:"a simplified cursive form of the ancient hieratic script",clip:1},"wx-demotic":{src:"concept:67:words:7:ex",route:"#/word/demotic",cta:"Open the word card",title:"In a sentence · demotic",body:"Demotic script was eventually replaced by Greek",clip:1},"wh-demotic":{src:"concept:67:words:7:hook",route:"#/word/demotic",cta:"Open the word card",title:"Remember it · demotic",body:"DEMOTIC script was for DEMO-cratic common people—both share 'demo' from demos."},"wo-demotic":{src:"lore:demotic:0",route:"#/word/demotic",cta:"Open the word card",title:"Where it comes from · demotic",body:"Greek demotikos = of the common people, from demos = people"},"wd-demiurge":{src:"concept:67:words:8:def",route:"#/word/demiurge",cta:"Open the word card",title:"demiurge",roman:"DEM-ee-urj",body:"a subordinate deity, in some philosophies the creator of the universe",clip:1},"wx-demiurge":{src:"concept:67:words:8:ex",route:"#/word/demiurge",cta:"Open the word card",title:"In a sentence · demiurge",body:"In ancient Gnostic belief, the demiurge was responsible for shaping the physical world from raw matter.",clip:1},"wh-demiurge":{src:"concept:67:words:8:hook",route:"#/word/demiurge",cta:"Open the word card",title:"Remember it · demiurge",body:"The DEMI-URGE-d creator URGED matter into form — the DEMI-URGE worked for the people (demos)."},"wo-demiurge":{src:"lore:demiurge:0",route:"#/word/demiurge",cta:"Open the word card",title:"Where it comes from · demiurge",body:"Greek demiourgos = craftsman, from demos = people + ergon = work"},"wd-democratize":{src:"concept:67:words:9:def",route:"#/word/democratize",cta:"Open the word card",title:"democratize",roman:"dih-MAH-kruh-teyez",body:"become (more) democratic; of nations",clip:1},"wx-democratize":{src:"concept:67:words:9:ex",route:"#/word/democratize",cta:"Open the word card",title:"In a sentence · democratize",body:"The internet has helped democratize information by making knowledge available to anyone with a connection.",clip:1},"wh-democratize":{src:"concept:67:words:9:hook",route:"#/word/democratize",cta:"Open the word card",title:"Remember it · democratize",body:"To democratIZE, you let the people RISE with a Z."},"wd-plutocracy":{src:"concept:67:words:11:def",route:"#/word/plutocracy",cta:"Open the word card",title:"plutocracy",roman:"ploo-TOK-ruh-see",body:"a political system governed by the wealthy people",clip:1},"wx-plutocracy":{src:"concept:67:words:11:ex",route:"#/word/plutocracy",cta:"Open the word card",title:"In a sentence · plutocracy",body:"Citizens protested what they called a plutocracy, where only the wealthiest had any real power.",clip:1},"wh-plutocracy":{src:"concept:67:words:11:hook",route:"#/word/plutocracy",cta:"Open the word card",title:"Remember it · plutocracy",body:"PLUTO (wealth god) + CRACY (rule) — rule by PLUTO's crowd: PLUTOCRACY."},"wd-theocracy":{src:"concept:67:words:12:def",route:"#/word/theocracy",cta:"Open the word card",title:"theocracy",roman:"th-ee-AH-k-r-uh-s-ee",body:"a form of government in which a deity is recognized as the supreme civil ruler",clip:1},"wx-theocracy":{src:"concept:67:words:12:ex",route:"#/word/theocracy",cta:"Open the word card",title:"In a sentence · theocracy",body:"In a theocracy, religious leaders make the laws of the land based on sacred texts and divine authority.",clip:1},"wh-theocracy":{src:"concept:67:words:12:hook",route:"#/word/theocracy",cta:"Open the word card",title:"Remember it · theocracy",body:"THEOCRACY: THEO (God) + CRACY (rule) — like DEMOcracy but God's in charge, not the DEMO."},"wo-theocracy":{src:"lore:theocracy:0",route:"#/word/theocracy",cta:"Open the word card",title:"Where it comes from · theocracy",body:"Greek theos = god + kratos = rule"},"li-u65":{src:"concept:68:concept",route:"#/stop/u65",cta:"Open this stop",title:"aud (hear)",body:"Latin audire = to hear. Everything about hearing and listening uses this root — from the audience that listens to audacious daring (a false friend: same letters, different root!)."},"lc-u65-0":{src:"concept:68:cards:0",route:"#/stop/u65",cta:"Open this stop",title:"aud (hear) · The Root",body:"Latin audire = to hear. Audible = able to be heard. Audience = those who come to hear. Auditorium = a place for hearing. Audit = originally an oral examination (hearing accounts). Audiovisual = combining sound and sight. All hearing-related — all from aud-."},"lc-u65-1":{src:"concept:68:cards:1",route:"#/stop/u65",cta:"Open this stop",title:"aud (hear) · The Audacious Trap",body:"⚠️ Audacious shares aud- BUT comes from audere = to dare (different Latin root!). Audible (hearing) ≠ audacious (daring). Both share A-U-D at the start. The definition is the only way to know which root you are dealing with. This is a famous bee confusable."},"lc-u65-2":{src:"concept:68:cards:2",route:"#/stop/u65",cta:"Open this stop",title:"aud (hear) · aud- in Legal/Formal Contexts",body:"Audit = an official hearing/examination of financial records. Auditor = one who audits. Judicial — NOT from aud-. Inaudible (in- + audible) = cannot be heard. Audition = a hearing/trial performance. Audiometry (aud- + -metry) = measurement of hearing."},"lc-u65-3":{src:"concept:68:cards:3",route:"#/stop/u65",cta:"Open this stop",title:"aud (hear) · Subaudition",body:'A rare but beautiful word: subaudition (sub- + audit + -ion) = understanding something that is not explicitly stated — the meaning you "hear under" the words. Also: subaudible = below the threshold of hearing. These show how aud- combines with other prefixes.'},"lc-u65-4":{src:"concept:68:cards:4",route:"#/stop/u65",cta:"Open this stop",title:"aud (hear) · Spelling aud- Words",body:"All begin A-U-D — the au diphthong sounds like /aw/. Audacious ≠ from audire but still spelled A-U-D. Auditorium = A-U-D-I-T-O-R-I-U-M (note the -torium from auditor + -ium = place for). Audible = A-U-D-I-B-L-E (-ible not -able — Latin stem)."},"uq-u65-3":{src:"unit:u65:qs:3",route:"#/stop/u65",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁ uses -IBLE not -ABLE: you need your EAR (AUD) to make it ▁▁▁ — 'I' hear it!” — which word is this hook about?",opts:["audible","audience","auditorium","audit"],after:"From “aud (hear)”."}},"wd-audible":{src:"concept:68:words:0:def",route:"#/word/audible",cta:"Open the word card",title:"audible",roman:"AH-duh-buhl",body:"a football play is changed orally after both teams have assumed their positions at the line of scrimmage",clip:1},"wx-audible":{src:"concept:68:words:0:ex",route:"#/word/audible",cta:"Open the word card",title:"In a sentence · audible",body:"he spoke in an audible whisper",clip:1},"wh-audible":{src:"concept:68:words:0:hook",route:"#/word/audible",cta:"Open the word card",title:"Remember it · audible",body:"AUDIBLE uses -IBLE not -ABLE: you need your EAR (AUD) to make it audIBLE — 'I' hear it!"},"wd-audience":{src:"concept:68:words:1:def",route:"#/word/audience",cta:"Open the word card",title:"audience",roman:"AH-dee-uhns",body:"a gathering of spectators or listeners at a (usually public) performance",clip:1},"wx-audience":{src:"concept:68:words:1:ex",route:"#/word/audience",cta:"Open the word card",title:"In a sentence · audience",body:"The audience burst into applause when the young violinist finished her breathtaking performance.",clip:1},"wh-audience":{src:"concept:68:words:1:hook",route:"#/word/audience",cta:"Open the word card",title:"Remember it · audience",body:"An AUDIence uses their ears — like an AUDIO system"},"wo-audience":{src:"lore:audience:0",route:"#/word/audience",cta:"Open the word card",title:"Where it comes from · audience",body:"Latin 'audire' = to hear + '-entia' = state or condition"},"wd-auditorium":{src:"concept:68:words:2:def",route:"#/word/auditorium",cta:"Open the word card",title:"auditorium",roman:"aw-duh-TAW-ree-uhm",body:"the area of a theater or concert hall where the audience sits",clip:1},"wx-auditorium":{src:"concept:68:words:2:ex",route:"#/word/auditorium",cta:"Open the word card",title:"In a sentence · auditorium",body:"The entire student body packed into the auditorium to watch the final spelling bee championship.",clip:1},"wh-auditorium":{src:"concept:68:words:2:hook",route:"#/word/auditorium",cta:"Open the word card",title:"Remember it · auditorium",body:"An audiTORIUM is a place where audiences hear — keep AUDI at the front, like listening."},"wo-auditorium":{src:"lore:auditorium:0",route:"#/word/auditorium",cta:"Open the word card",title:"Where it comes from · auditorium",body:"Latin auditorium = place for hearing"},"wd-audit":{src:"concept:68:words:3:def",route:"#/word/audit",cta:"Open the word card",title:"audit",roman:"AW-diht",body:"an inspection of the accounting procedures and records by a trained accountant or CPA",clip:1},"wx-audit":{src:"concept:68:words:3:ex",route:"#/word/audit",cta:"Open the word card",title:"In a sentence · audit",body:"he made an audit of all the plants on his property",clip:1},"wh-audit":{src:"concept:68:words:3:hook",route:"#/word/audit",cta:"Open the word card",title:"Remember it · audit",body:"An AUDIT is when the accountant 'hears' the books — Latin 'he heard': A-U-D-I-T, just five letters, one T."},"wo-audit":{src:"lore:audit:0",route:"#/word/audit",cta:"Open the word card",title:"Where it comes from · audit",body:"Latin 'audire' (to hear) — accounts were once read aloud for checking."},"wd-audition":{src:"concept:68:words:4:def",route:"#/word/audition",cta:"Open the word card",title:"audition",roman:"ah-DIH-shuhn",body:"the ability to hear; the auditory faculty",clip:1},"wx-audition":{src:"concept:68:words:4:ex",route:"#/word/audition",cta:"Open the word card",title:"In a sentence · audition",body:"Keen audition lets a barn owl hear a mouse rustling under deep snow.",clip:1},"wh-audition":{src:"concept:68:words:4:hook",route:"#/word/audition",cta:"Open the word card",title:"Remember it · audition",body:"An audITION is your chance to be heard — hear the word 'ITION' as you perform."},"wo-audition":{src:"lore:audition:0",route:"#/word/audition",cta:"Open the word card",title:"Where it comes from · audition",body:"Latin auditio = a hearing"},"wd-inaudible":{src:"concept:68:words:6:def",route:"#/word/inaudible",cta:"Open the word card",title:"inaudible",roman:"ih-NAW-duh-buhl",body:"impossible to hear; imperceptible by the ear",clip:1},"wx-inaudible":{src:"concept:68:words:6:ex",route:"#/word/inaudible",cta:"Open the word card",title:"In a sentence · inaudible",body:"an inaudible conversation",clip:1},"wh-inaudible":{src:"concept:68:words:6:hook",route:"#/word/inaudible",cta:"Open the word card",title:"Remember it · inaudible",body:"Inaudible ends in -IBLE not -ABLE — AUD as in AUDIO cannot be heard here."},"wo-inaudible":{src:"lore:inaudible:0",route:"#/word/inaudible",cta:"Open the word card",title:"Where it comes from · inaudible",body:"Latin audire = to hear"},"wd-audiovisual":{src:"concept:68:words:7:def",route:"#/word/audiovisual",cta:"Open the word card",title:"audiovisual",roman:"aw-dee-oh-VIH-zhoo-uhl",body:"materials using sight or sound to present information",clip:1},"wx-audiovisual":{src:"concept:68:words:7:ex",route:"#/word/audiovisual",cta:"Open the word card",title:"In a sentence · audiovisual",body:"language tapes and videocassettes and other audiovisuals",clip:1},"wh-audiovisual":{src:"concept:68:words:7:hook",route:"#/word/audiovisual",cta:"Open the word card",title:"Remember it · audiovisual",body:"AUDIOVISUAL combines hearing AND seeing — AUDIO + VISUAL, both senses in one long word ending in -UAL."},"wo-audiovisual":{src:"lore:audiovisual:0",route:"#/word/audiovisual",cta:"Open the word card",title:"Where it comes from · audiovisual",body:"Latin audire = to hear + Latin videre = to see"},"wd-auditor":{src:"concept:68:words:8:def",route:"#/word/auditor",cta:"Open the word card",title:"auditor",roman:"AW-dih-ter",body:"someone who listens attentively",clip:1},"wx-auditor":{src:"concept:68:words:8:ex",route:"#/word/auditor",cta:"Open the word card",title:"In a sentence · auditor",body:"The auditor carefully reviewed every financial record to make sure there were no errors in the company's accounts.",clip:1},"wh-auditor":{src:"concept:68:words:8:hook",route:"#/word/auditor",cta:"Open the word card",title:"Remember it · auditor",body:"An audiTOR is a person who listens and checks — TOR sounds like 'tore through the books'."},"wd-subaudition":{src:"concept:68:words:9:def",route:"#/word/subaudition",cta:"Open the word card",title:"subaudition",roman:"sub-aw-DISH-un",body:"The mental act of understanding or supplying something that is implied but not directly stated in speech or writing.",clip:1},"wx-subaudition":{src:"concept:68:words:9:ex",route:"#/word/subaudition",cta:"Open the word card",title:"In a sentence · subaudition",body:"The reader used subaudition to fill in the missing word that the damaged manuscript had lost.",clip:1},"wh-subaudition":{src:"concept:68:words:9:hook",route:"#/word/subaudition",cta:"Open the word card",title:"Remember it · subaudition",body:"SUB + AUDITION — hearing what's BELOW the text, mentally AUDITING what isn't said."},"wo-subaudition":{src:"lore:subaudition:0",route:"#/word/subaudition",cta:"Open the word card",title:"Where it comes from · subaudition",body:"Latin: subaudire (Latin)"},"li-u66":{src:"concept:69:concept",route:"#/stop/u66",cta:"Open this stop",title:"dict / dic (say / speak)",body:"Latin dicere = to say. One of the most productive roots in legal, political, and everyday English. Every time something is said officially, pronounced, or declared, dict- is likely present."},"lc-u66-0":{src:"concept:69:cards:0",route:"#/stop/u66",cta:"Open this stop",title:"dict / dic (say / speak) · The Root",body:"Latin dicere = to say. Diction = the way one says words = enunciation. Dictate = say officially. Edict (e- = out + dict) = what is said officially = a decree. Indict (in- + dict) = formally accuse (the c is silent in English: /in-DYTE/!). Verdict (ver = truth + dict) = what is truly said by a jury."},"lc-u66-1":{src:"concept:69:cards:1",route:"#/stop/u66",cta:"Open this stop",title:"dict / dic (say / speak) · Bene- and Male-diction",body:"Benediction (bene + dict + -ion) = a good saying = a blessing. Malediction (male + dict + -ion) = a bad saying = a curse. These are structural opposites built from the same dict- root. In a bee: benediction = B-E-N-E-D-I-C-T-I-O-N; malediction = M-A-L-E-D-I-C-T-I-O-N."},"lc-u66-2":{src:"concept:69:cards:2",route:"#/stop/u66",cta:"Open this stop",title:"dict / dic (say / speak) · Contradict & Predict",body:"Contradict (contra- = against + dict) = say against = dispute. Predict (pre- + dict) = say before = forecast. Interdict (inter- + dict) = say between/forbid. Valediction (vale = farewell + dict) = a farewell saying. Jurisdiction (juris = law + dict) = saying what the law is = legal authority."},"lc-u66-3":{src:"concept:69:cards:3",route:"#/stop/u66",cta:"Open this stop",title:"dict / dic (say / speak) · Abdicate vs Dedicate",body:"⚠️ Neither abdicate nor dedicate is from dicere = say. Abdicate comes from abdicare = renounce. Dedicate = dedicare = set apart for a purpose. These look like dict- words but use a different Latin root dicare (not dicere). The definition at the microphone resolves the confusion."},"lc-u66-4":{src:"concept:69:cards:4",route:"#/stop/u66",cta:"Open this stop",title:"dict / dic (say / speak) · Spelling dict- Words",body:"Indict = I-N-D-I-C-T (silent c — pronounced /in-DYTE/). Jurisdiction = J-U-R-I-S-D-I-C-T-I-O-N (note -juris- = law). Valediction = V-A-L-E-D-I-C-T-I-O-N (spoken at graduation). Malediction = M-A-L-E-D-I-C-T-I-O-N. The -dict- is always spelled the same: D-I-C-T."},"uq-u66-3":{src:"unit:u66:qs:3",route:"#/stop/u66",cta:"Open this stop",title:"Whose hook?",play:{q:"“Good ▁▁▁ means saying each DICT-ion clearly — no mumbling allowed.” — which word is this hook about?",opts:["diction","dictate","edict","indict"],after:"From “dict / dic (say / speak)”."}},"wd-diction":{src:"concept:69:words:0:def",route:"#/word/diction",cta:"Open the word card",title:"diction",roman:"DIH-kshuhn",body:"the articulation of speech regarded from the point of view of its intelligibility to the audience",clip:1},"wx-diction":{src:"concept:69:words:0:ex",route:"#/word/diction",cta:"Open the word card",title:"In a sentence · diction",body:"Clear diction carried Anya's poem to the back row without any microphone.",clip:1},"wh-diction":{src:"concept:69:words:0:hook",route:"#/word/diction",cta:"Open the word card",title:"Remember it · diction",body:"Good DICTION means saying each DICT-ion clearly — no mumbling allowed."},"wd-dictate":{src:"concept:69:words:1:def",route:"#/word/dictate",cta:"Open the word card",title:"dictate",roman:"dih-KTAYT",body:"an authoritative rule",clip:1},"wx-dictate":{src:"concept:69:words:1:ex",route:"#/word/dictate",cta:"Open the word card",title:"In a sentence · dictate",body:"the dictates of reason",clip:1},"wh-dictate":{src:"concept:69:words:1:hook",route:"#/word/dictate",cta:"Open the word card",title:"Remember it · dictate",body:"When you DICTATE, you say it — DICT sounds like 'dicked' out word by word."},"wd-edict":{src:"concept:69:words:2:def",route:"#/word/edict",cta:"Open the word card",title:"edict",roman:"EE-dihkt",body:"a formal or authoritative proclamation",clip:1},"wx-edict":{src:"concept:69:words:2:ex",route:"#/word/edict",cta:"Open the word card",title:"In a sentence · edict",body:"By royal edict, every market in the kingdom had to close at sunset.",clip:1},"wh-edict":{src:"concept:69:words:2:hook",route:"#/word/edict",cta:"Open the word card",title:"Remember it · edict",body:"An EDICT is DICTATED outward — one 'd', like in DICTATE."},"wo-edict":{src:"lore:edict:0",route:"#/word/edict",cta:"Open the word card",title:"Where it comes from · edict",body:"Latin edictum, from edicere = to proclaim (e-out + dicere-say)"},"wd-indict":{src:"concept:69:words:3:def",route:"#/word/indict",cta:"Open the word card",title:"indict",roman:"ih-NDEYET",body:"accuse formally of a crime",clip:1},"wx-indict":{src:"concept:69:words:3:ex",route:"#/word/indict",cta:"Open the word card",title:"In a sentence · indict",body:"The grand jury voted to indict the corrupt official on three counts of fraud and bribery.",clip:1},"wh-indict":{src:"concept:69:words:3:hook",route:"#/word/indict",cta:"Open the word card",title:"Remember it · indict",body:"You inDICT someone in DICT-ation — the C is silent but it's always there, hiding like evidence."},"wd-verdict":{src:"concept:69:words:4:def",route:"#/word/verdict",cta:"Open the word card",title:"verdict",roman:"VUR-dihkt",body:"in law, the findings of a jury on issues of fact submitted to it for decision; can be used in formulating a judgment",clip:1},"wx-verdict":{src:"concept:69:words:4:ex",route:"#/word/verdict",cta:"Open the word card",title:"In a sentence · verdict",body:"The courtroom fell completely silent as the jury foreman rose to announce the long-awaited verdict.",clip:1},"wh-verdict":{src:"concept:69:words:4:hook",route:"#/word/verdict",cta:"Open the word card",title:"Remember it · verdict",body:"A VERDICT is what is truly DICT-ated (said) by the jury — VERily DiCTated!"},"wd-benediction":{src:"concept:69:words:5:def",route:"#/word/benediction",cta:"Open the word card",title:"benediction",roman:"beh-nuh-DIH-kshuhn",body:"the act of praying for divine protection",clip:1},"wx-benediction":{src:"concept:69:words:5:ex",route:"#/word/benediction",cta:"Open the word card",title:"In a sentence · benediction",body:"The priest offered a warm benediction at the end of the ceremony, sending the congregation home with words of peace and hope.",clip:1},"wh-benediction":{src:"concept:69:words:5:hook",route:"#/word/benediction",cta:"Open the word card",title:"Remember it · benediction",body:"A BENEficial DICTION: a benediction is literally 'well-spoken' words of blessing."},"wo-benediction":{src:"lore:benediction:0",route:"#/word/benediction",cta:"Open the word card",title:"Where it comes from · benediction",body:"Latin bene = well + dicere = to say/speak"},"wx-contradict":{src:"concept:69:words:7:ex",route:"#/word/contradict",cta:"Open the word card",title:"In a sentence · contradict",body:"Ravi politely contradicted his brother, explaining that the museum opens at ten, not nine.",clip:1},"wh-contradict":{src:"concept:69:words:7:hook",route:"#/word/contradict",cta:"Open the word card",title:"Remember it · contradict",body:"To CONTRADICT is to say something AGAINST what was DICT-ated — contra + dict."},"wo-contradict":{src:"lore:contradict:0",route:"#/word/contradict",cta:"Open the word card",title:"Where it comes from · contradict",body:"Latin contra = against + dicere = to say"},"wd-predict":{src:"concept:69:words:8:def",route:"#/word/predict",cta:"Open the word card",title:"predict",roman:"prih-DIHKT",body:"make a prediction about; tell in advance",clip:1},"wx-predict":{src:"concept:69:words:8:ex",route:"#/word/predict",cta:"Open the word card",title:"In a sentence · predict",body:"Using pressure charts, weather scientists predict tomorrow's rain hours before a single cloud appears.",clip:1},"wh-predict":{src:"concept:69:words:8:hook",route:"#/word/predict",cta:"Open the word card",title:"Remember it · predict",body:"To preDICT is to DICT-ate the future before it happens — a DICTATOR tells you what will be."},"wd-interdict":{src:"concept:69:words:9:def",route:"#/word/interdict",cta:"Open the word card",title:"interdict",roman:"IH-nter-dihkt",body:"an ecclesiastical censure by the Roman Catholic Church withdrawing certain sacraments and Christian burial from a person or all persons in a particular district",clip:1},"wx-interdict":{src:"concept:69:words:9:ex",route:"#/word/interdict",cta:"Open the word card",title:"In a sentence · interdict",body:"The pope placed the rebellious city under an interdict, closing its churches for a whole year.",clip:1},"wh-interdict":{src:"concept:69:words:9:hook",route:"#/word/interdict",cta:"Open the word card",title:"Remember it · interdict",body:"A DICT-ator steps INTER (between) you and your rights — interDICT contains 'dict' like dictate."},"wo-interdict":{src:"lore:interdict:0",route:"#/word/interdict",cta:"Open the word card",title:"Where it comes from · interdict",body:"Latin inter = between + dicere = to say/decree"},"wd-jurisdiction":{src:"concept:69:words:11:def",route:"#/word/jurisdiction",cta:"Open the word card",title:"jurisdiction",roman:"juu-ruh-SDIH-kshuhn",body:"in law, the right and power to interpret and apply the law",clip:1},"wx-jurisdiction":{src:"concept:69:words:11:ex",route:"#/word/jurisdiction",cta:"Open the word card",title:"In a sentence · jurisdiction",body:"The local police explained that the crime had occurred just outside their jurisdiction and another department would handle it.",clip:1},"wh-jurisdiction":{src:"concept:69:words:11:hook",route:"#/word/jurisdiction",cta:"Open the word card",title:"Remember it · jurisdiction",body:"Jurisdiction: the JURIS (law) DICTION (words) of authority."},"wo-jurisdiction":{src:"lore:jurisdiction:0",route:"#/word/jurisdiction",cta:"Open the word card",title:"Where it comes from · jurisdiction",body:"Latin jurisdictio, from jus/juris(law)+dicere(to say/declare)"},"wd-abdicate":{src:"concept:69:words:12:def",route:"#/word/abdicate",cta:"Open the word card",title:"abdicate",roman:"A-bduh-kayt",body:"To formally give up or renounce a high office, throne, or position of power or responsibility.",clip:1},"wx-abdicate":{src:"concept:69:words:12:ex",route:"#/word/abdicate",cta:"Open the word card",title:"In a sentence · abdicate",body:"When the king decided to abdicate his throne, the entire kingdom was stunned and uncertain about who would rule next.",clip:1},"wh-abdicate":{src:"concept:69:words:12:hook",route:"#/word/abdicate",cta:"Open the word card",title:"Remember it · abdicate",body:"To abdicate is to 'declare away' your power—the 'dic' root means to declare."},"wo-abdicate":{src:"lore:abdicate:0",route:"#/word/abdicate",cta:"Open the word card",title:"Where it comes from · abdicate",body:"Latin abdicare from ab-(away)+dicare(to declare or proclaim)"},"wd-dedicating":{src:"concept:69:words:13:def",route:"#/word/dedicating",cta:"Open the word card",title:"dedicating",roman:"DEH-dih-kay-tihng",body:"give entirely to a specific person, activity, or cause",clip:1},"wx-dedicating":{src:"concept:69:words:13:ex",route:"#/word/dedicating",cta:"Open the word card",title:"In a sentence · dedicating",body:"By dedicating one hour each evening to violin, Nina mastered the difficult concerto.",clip:1},"wh-dedicating":{src:"concept:69:words:13:hook",route:"#/word/dedicating",cta:"Open the word card",title:"Remember it · dedicating",body:"Drop the E before adding -ING: DEDICATING, not dedicateing."},"wo-dedicating":{src:"lore:dedicating:0",route:"#/word/dedicating",cta:"Open the word card",title:"Where it comes from · dedicating",body:"Latin dedicare = to declare, consecrate"},"li-u67":{src:"concept:70:concept",route:"#/stop/u67",cta:"Open this stop",title:"duc / duct (lead)",body:"Latin ducere = to lead. From education (leading out knowledge) to seduction (leading aside), this root describes every form of leading, guiding, and conducting."},"lc-u67-0":{src:"concept:70:cards:0",route:"#/stop/u67",cta:"Open this stop",title:"duc / duct (lead) · The Root",body:"Latin ducere = to lead. Induct = lead into a position. Educate (e- = out + duc) = lead knowledge outward from within. Introduce (intro- = within + duce) = lead into the presence of. Conduct (con- = together + duct) = lead together. Reduce (re- = back + duce) = lead back = make smaller."},"lc-u67-1":{src:"concept:70:cards:1",route:"#/stop/u67",cta:"Open this stop",title:"duc / duct (lead) · Duke & Duchess",body:'Duke = dux = the leader. From ducere → dux → Old French duc → English duke. A duke is literally "a leader." Aqueduct (aqua = water + ductus) = a structure that leads water. Viaduct (via = road + ductus) = a structure that leads a road across a valley.'},"lc-u67-2":{src:"concept:70:cards:2",route:"#/stop/u67",cta:"Open this stop",title:"duc / duct (lead) · Abduct, Deduct, Seduce",body:"Abduct (ab- = away) = lead away by force. Deduct (de- = from) = lead/take from the total. Seduce (se- = aside) = lead aside = lead astray. Traduce (tra- = across) = lead across = to slander. Adduce (ad- = toward) = lead toward = to cite as evidence. Each prefix changes the direction of leading."},"lc-u67-3":{src:"concept:70:cards:3",route:"#/stop/u67",cta:"Open this stop",title:"duc / duct (lead) · Conductor & Semiconductor",body:"Conductor = one who leads (an orchestra or electricity). Semiconductor (semi- = half) = a material that half-conducts electricity (silicon in computer chips). Nonconductor = does not conduct. Superconductor (super- = above) = conducts with zero resistance."},"lc-u67-4":{src:"concept:70:cards:4",route:"#/stop/u67",cta:"Open this stop",title:"duc / duct (lead) · Spelling duc/duct Words",body:"The root appears as duc (before vowels: educate, reduce, seduce) and duct (before consonants: induction, conduction, abduction). Aqueduct = A-Q-U-E-D-U-C-T (Latin aqua = water). Viaduct = V-I-A-D-U-C-T (via = road). Educate = E-D-U-C-A-T-E (e- + duc + -ate)."},"uq-u67-3":{src:"unit:u67:qs:3",route:"#/stop/u67",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁ has the word DUCT in it — like a duct leading you IN to a new role.” — which word is this hook about?",opts:["induction","educate","conduct","reduce"],after:"From “duc / duct (lead)”."}},"wd-induction":{src:"concept:70:words:0:def",route:"#/word/induction",cta:"Open the word card",title:"induction",roman:"ih-NDUH-kshuhn",body:"a formal entry into an organization or position or office",clip:1},"wx-induction":{src:"concept:70:words:0:ex",route:"#/word/induction",cta:"Open the word card",title:"In a sentence · induction",body:"At the induction ceremony, new club members received badges and signed the pledge book.",clip:1},"wh-induction":{src:"concept:70:words:0:hook",route:"#/word/induction",cta:"Open the word card",title:"Remember it · induction",body:"INDUCTION has the word DUCT in it — like a duct leading you IN to a new role."},"wo-induction":{src:"lore:induction:0",route:"#/word/induction",cta:"Open the word card",title:"Where it comes from · induction",body:"Latin inductio = a leading in"},"wd-educate":{src:"concept:70:words:1:def",route:"#/word/educate",cta:"Open the word card",title:"educate",roman:"EH-juh-kayt",body:"give an education to",clip:1},"wx-educate":{src:"concept:70:words:1:ex",route:"#/word/educate",cta:"Open the word card",title:"In a sentence · educate",body:"We must educate our youngsters better",clip:1},"wh-educate":{src:"concept:70:words:1:hook",route:"#/word/educate",cta:"Open the word card",title:"Remember it · educate",body:"EDUCATE has a DUCK in the middle — a teacher leads ducklings out to learn."},"wd-conduct":{src:"concept:70:words:2:def",route:"#/word/conduct",cta:"Open the word card",title:"conduct",roman:"KAH-nduhkt",body:"manner of acting or controlling yourself",clip:1},"wx-conduct":{src:"concept:70:words:2:ex",route:"#/word/conduct",cta:"Open the word card",title:"In a sentence · conduct",body:"You cannot conduct business like this",clip:1},"wh-conduct":{src:"concept:70:words:2:hook",route:"#/word/conduct",cta:"Open the word card",title:"Remember it · conduct",body:"CONDUCT — a CONDUCTor LEADS the orchestra. CON+DUCT, no extra letters hidden inside."},"wd-reduce":{src:"concept:70:words:3:def",route:"#/word/reduce",cta:"Open the word card",title:"reduce",roman:"ruh-DOOS",body:"cut down on; make a reduction in",clip:1},"wx-reduce":{src:"concept:70:words:3:ex",route:"#/word/reduce",cta:"Open the word card",title:"In a sentence · reduce",body:"reduce your daily fat intake",clip:1},"wh-reduce":{src:"concept:70:words:3:hook",route:"#/word/reduce",cta:"Open the word card",title:"Remember it · reduce",body:"The DUKE led things BACK — reDUCE ends in DUCE, like a duke leading things down."},"wd-introduce":{src:"concept:70:words:4:def",route:"#/word/introduce",cta:"Open the word card",title:"introduce",roman:"ih-ntruh-DOOS",body:"cause to come to know personally",clip:1},"wx-introduce":{src:"concept:70:words:4:ex",route:"#/word/introduce",cta:"Open the word card",title:"In a sentence · introduce",body:"Let me introduce you to Sara, the girl who built our robot's grabbing arm.",clip:1},"wh-introduce":{src:"concept:70:words:4:hook",route:"#/word/introduce",cta:"Open the word card",title:"Remember it · introduce",body:"Introduce uses -duce like 'conduct' or 'deduce'—you LEAD someone IN."},"wo-introduce":{src:"lore:introduce:0",route:"#/word/introduce",cta:"Open the word card",title:"Where it comes from · introduce",body:"Latin introducere = to lead in"},"wd-abduct":{src:"concept:70:words:5:def",route:"#/word/abduct",cta:"Open the word card",title:"abduct",roman:"a-BDUHKT",body:"To take someone away by force or illegally, such as in a kidnapping; also, in anatomy, to move a limb away from the body's midline.",clip:1},"wx-abduct":{src:"concept:70:words:5:ex",route:"#/word/abduct",cta:"Open the word card",title:"In a sentence · abduct",body:"The villain's plot to abduct the young princess was foiled by the brave knights who had been standing guard.",clip:1},"wh-abduct":{src:"concept:70:words:5:hook",route:"#/word/abduct",cta:"Open the word card",title:"Remember it · abduct",body:"ab- (away) + duct (lead): to lead someone away against their will"},"wo-abduct":{src:"lore:abduct:0",route:"#/word/abduct",cta:"Open the word card",title:"Where it comes from · abduct",body:"Latin abductus, past participle of abducere, from ab- meaning away + ducere meaning to lead"},"wd-deduct":{src:"concept:70:words:6:def",route:"#/word/deduct",cta:"Open the word card",title:"deduct",roman:"dih-DUHKT",body:"make a subtraction",clip:1},"wx-deduct":{src:"concept:70:words:6:ex",route:"#/word/deduct",cta:"Open the word card",title:"In a sentence · deduct",body:"Judges deduct two points every time a gymnast steps outside the mat.",clip:1},"wh-deduct":{src:"concept:70:words:6:hook",route:"#/word/deduct",cta:"Open the word card",title:"Remember it · deduct",body:"DE-DUCT: a DUCT leads water away — DEDUCT leads money away from your total."},"wd-traduce":{src:"concept:70:words:8:def",route:"#/word/traduce",cta:"Open the word card",title:"traduce",roman:"truh-DYOOS",body:"means to slander or defame",clip:1},"wx-traduce":{src:"concept:70:words:8:ex",route:"#/word/traduce",cta:"Open the word card",title:"In a sentence · traduce",body:"It is unfair to traduce a classmate by spreading stories you know are false.",clip:1},"wh-traduce":{src:"concept:70:words:8:hook",route:"#/word/traduce",cta:"Open the word card",title:"Remember it · traduce",body:"To TRADUCE someone is to lead their reputation across the mud — like PRODUCE but with TRA-, producing lies about someone."},"wo-traduce":{src:"lore:traduce:0",route:"#/word/traduce",cta:"Open the word card",title:"Where it comes from · traduce",body:"Latin traducere = to lead across, expose to ridicule"},"wd-adduce":{src:"concept:70:words:9:def",route:"#/word/adduce",cta:"Open the word card",title:"adduce",roman:"ah-DOOS",body:"advance evidence for",clip:1},"wx-adduce":{src:"concept:70:words:9:ex",route:"#/word/adduce",cta:"Open the word card",title:"In a sentence · adduce",body:"The defense attorney tried to adduce new witnesses and documents to support her client's alibi.",clip:1},"wh-adduce":{src:"concept:70:words:9:hook",route:"#/word/adduce",cta:"Open the word card",title:"Remember it · adduce",body:"To adduce evidence, you LEAD it forward — the double D leads duce right to the judge."},"wd-aqueduct":{src:"concept:70:words:10:def",route:"#/word/aqueduct",cta:"Open the word card",title:"aqueduct",roman:"A-kwuh-duhkt",body:"a conduit that resembles a bridge but carries water over a valley",clip:1},"wx-aqueduct":{src:"concept:70:words:10:ex",route:"#/word/aqueduct",cta:"Open the word card",title:"In a sentence · aqueduct",body:"The ancient Roman aqueduct still stretches across the valley, a testament to brilliant engineering.",clip:1},"wh-aqueduct":{src:"concept:70:words:10:hook",route:"#/word/aqueduct",cta:"Open the word card",title:"Remember it · aqueduct",body:"AquEDUCT not aquADUCT — the E is the bridge that carries water, just like the structure itself."},"wo-aqueduct":{src:"lore:aqueduct:0",route:"#/word/aqueduct",cta:"Open the word card",title:"Where it comes from · aqueduct",body:"Latin aqua = water + ducere = to lead/carry"},"wd-viaduct":{src:"concept:70:words:11:def",route:"#/word/viaduct",cta:"Open the word card",title:"viaduct",roman:"VEYE-uh-duhkt",body:"bridge consisting of a series of arches supported by piers used to carry a road (or railroad) over a valley",clip:1},"wx-viaduct":{src:"concept:70:words:11:ex",route:"#/word/viaduct",cta:"Open the word card",title:"In a sentence · viaduct",body:"The old stone viaduct carried the railroad across the deep valley for over a hundred years.",clip:1},"wh-viaduct":{src:"concept:70:words:11:hook",route:"#/word/viaduct",cta:"Open the word card",title:"Remember it · viaduct",body:"A VIAduct leads (DUCT) the road (VIA) over a valley — road + conduit = viaduct."},"wo-viaduct":{src:"lore:viaduct:0",route:"#/word/viaduct",cta:"Open the word card",title:"Where it comes from · viaduct",body:"Latin via = road, way + ducere = to lead"},"wd-conductor":{src:"concept:70:words:12:def",route:"#/word/conductor",cta:"Open the word card",title:"conductor",roman:"kuh-NDUH-kter",body:"the person who leads a musical group",clip:1},"wx-conductor":{src:"concept:70:words:12:ex",route:"#/word/conductor",cta:"Open the word card",title:"In a sentence · conductor",body:"The conductor raised her baton and the entire orchestra fell into perfect silence.",clip:1},"wh-conductor":{src:"concept:70:words:12:hook",route:"#/word/conductor",cta:"Open the word card",title:"Remember it · conductor",body:"A conducTOR leads the orchestra — remember the -OR ending, because he's a leaDOR of sound."},"wo-conductor":{src:"lore:conductor:0",route:"#/word/conductor",cta:"Open the word card",title:"Where it comes from · conductor",body:"Latin conducere = to lead together, from con-(together)+ducere(to lead)"},"wd-semiconductor":{src:"concept:70:words:13:def",route:"#/word/semiconductor",cta:"Open the word card",title:"semiconductor",roman:"seh-mee-kuh-NDUH-kter",body:"a substance as germanium or silicon whose electrical conductivity is intermediate between that of a metal and an insulator; its conductivity increases with temperature and in the presence of impurities",clip:1},"wx-semiconductor":{src:"concept:70:words:13:ex",route:"#/word/semiconductor",cta:"Open the word card",title:"In a sentence · semiconductor",body:"Silicon, a widely used semiconductor, is the key ingredient in most modern computer chips.",clip:1},"wh-semiconductor":{src:"concept:70:words:13:hook",route:"#/word/semiconductor",cta:"Open the word card",title:"Remember it · semiconductor",body:"SEMICONDUCTOR ends in OR — the conductor leads the charge, so honor it with an O-R ending."},"wo-semiconductor":{src:"lore:semiconductor:0",route:"#/word/semiconductor",cta:"Open the word card",title:"Where it comes from · semiconductor",body:"Latin semi = half + conducere = to lead together"},"wd-ductile":{src:"concept:70:words:14:def",route:"#/word/ductile",cta:"Open the word card",title:"ductile",roman:"DUH-ktuhl",body:"easily influenced",clip:1},"wx-ductile":{src:"concept:70:words:14:ex",route:"#/word/ductile",cta:"Open the word card",title:"In a sentence · ductile",body:"Gold is an extremely ductile metal, meaning skilled jewelers can hammer and stretch it into incredibly thin wires without the material cracking or breaking apart.",clip:1},"wh-ductile":{src:"concept:70:words:14:hook",route:"#/word/ductile",cta:"Open the word card",title:"Remember it · ductile",body:"A ductile wire can be DUCT-tiled flat — stretched into any tile shape you need."},"wd-inductee":{src:"concept:70:words:15:def",route:"#/word/inductee",cta:"Open the word card",title:"inductee",roman:"ih-nduh-KTEE",body:"a person inducted into an organization or social group",clip:1},"wx-inductee":{src:"concept:70:words:15:ex",route:"#/word/inductee",cta:"Open the word card",title:"In a sentence · inductee",body:"Ty Cobb and Babe Ruth were 1936 inductees in the National Baseball Hall of Fame",clip:1},"wh-inductee":{src:"concept:70:words:15:hook",route:"#/word/inductee",cta:"Open the word card",title:"Remember it · inductee",body:"The inductEE is the one being led IN — double E at the end like two open doors welcoming them."},"li-u68":{src:"concept:71:concept",route:"#/stop/u68",cta:"Open this stop",title:"fer (carry / bear)",body:"Latin ferre = to carry, to bear. One of the most productive Latin roots — it appears in scientific (conifer, fertile), legal (transfer), and everyday (prefer, suffer) vocabulary."},"lc-u68-0":{src:"concept:71:cards:0",route:"#/stop/u68",cta:"Open this stop",title:"fer (carry / bear) · The Root",body:"Latin ferre = to carry, bear. Transfer (trans- = across) = carry across. Confer (con- = together) = carry/bring together = discuss. Defer (de- = away) = carry away = postpone or show respect. Infer (in- = toward) = carry toward a conclusion."},"lc-u68-1":{src:"concept:71:cards:1",route:"#/stop/u68",cta:"Open this stop",title:"fer (carry / bear) · -fer Words in Science",body:"Aquifer (aqua + -fer) = carries/bears water underground. Conifer (conus = cone + -fer) = cone-bearing tree. Crucifer (crux = cross + -fer) = cross-bearing plant (broccoli, cabbage). Proliferate (proles + -ferare) = carry offspring = spread abundantly."},"lc-u68-2":{src:"concept:71:cards:2",route:"#/stop/u68",cta:"Open this stop",title:"fer (carry / bear) · Suffer & Offer",body:"Suffer (sub- + ferre) = carry under = endure. Offer (ob- + ferre) = carry toward = present for acceptance. Afferent (ad- + ferens) = carrying toward (nerves carrying signals TO the brain). Efferent (e- + ferens) = carrying outward (nerves carrying signals FROM the brain)."},"lc-u68-3":{src:"concept:71:cards:3",route:"#/stop/u68",cta:"Open this stop",title:"fer (carry / bear) · Fertile & Fertile",body:"Fertile (fertilis = bearing fruit) = producing abundantly. Fertility = the state of being productive. Fertilize = make fertile. Infertile (in- + fertile) = unable to bear/produce. Fertilizer = substance that makes soil more productive. All from ferre = to bear → fertilis = bearing."},"lc-u68-4":{src:"concept:71:cards:4",route:"#/stop/u68",cta:"Open this stop",title:"fer (carry / bear) · Spelling fer- Words",body:"The fer root can appear as fer- or -fer- or -ferr- (when stress causes doubling): prefer → preferring (double-r because stress is on the second syllable). Refer → referred (double-r). Transfer → transferring (double-r). Offer → offered (no double — stress on first syllable)."},"uq-u68-3":{src:"unit:u68:qs:3",route:"#/stop/u68",cta:"Open this stop",title:"Whose hook?",play:{q:"“To ▁▁▁ is to FERRY something across — FER sounds like FERRY, carrying goods over water.” — which word is this hook about?",opts:["transfer","confer","defer","infer"],after:"From “fer (carry / bear)”."}},"wd-transfer":{src:"concept:71:words:0:def",route:"#/word/transfer",cta:"Open the word card",title:"transfer",roman:"tra-NSFUR",body:"the act of moving something from one location to another",clip:1},"wx-transfer":{src:"concept:71:words:0:ex",route:"#/word/transfer",cta:"Open the word card",title:"In a sentence · transfer",body:"the best student was a transfer from LSU",clip:1},"wh-transfer":{src:"concept:71:words:0:hook",route:"#/word/transfer",cta:"Open the word card",title:"Remember it · transfer",body:"To transFER is to FERRY something across — FER sounds like FERRY, carrying goods over water."},"wd-confer":{src:"concept:71:words:1:def",route:"#/word/confer",cta:"Open the word card",title:"confer",roman:"kuh-NFUR",body:"have a conference in order to talk something over",clip:1},"wx-confer":{src:"concept:71:words:1:ex",route:"#/word/confer",cta:"Open the word card",title:"In a sentence · confer",body:"We conferred about a plan of action",clip:1},"wh-confer":{src:"concept:71:words:1:hook",route:"#/word/confer",cta:"Open the word card",title:"Remember it · confer",body:"When you conFER, you bring ideas toFERther — FER is the engine that carries meaning."},"wd-defer":{src:"concept:71:words:2:def",route:"#/word/defer",cta:"Open the word card",title:"defer",roman:"dih-FUR",body:"hold back to a later time",clip:1},"wx-defer":{src:"concept:71:words:2:ex",route:"#/word/defer",cta:"Open the word card",title:"In a sentence · defer",body:"Heavy rain forced the coach to defer our match until next Saturday morning.",clip:1},"wh-defer":{src:"concept:71:words:2:hook",route:"#/word/defer",cta:"Open the word card",title:"Remember it · defer",body:"To deFER is to carry a decision FURther away — hear the FUR sound and picture pushing it away."},"wd-infer":{src:"concept:71:words:3:def",route:"#/word/infer",cta:"Open the word card",title:"infer",roman:"ih-NFUR",body:"reason by deduction; establish by deduction",clip:1},"wx-infer":{src:"concept:71:words:3:ex",route:"#/word/infer",cta:"Open the word card",title:"In a sentence · infer",body:"From the muddy paw prints, we could infer that a fox had crossed the garden.",clip:1},"wh-infer":{src:"concept:71:words:3:hook",route:"#/word/infer",cta:"Open the word card",title:"Remember it · infer",body:"To inFER, you carry facts inward — FER means carry, like a ferry."},"wo-infer":{src:"lore:infer:0",route:"#/word/infer",cta:"Open the word card",title:"Where it comes from · infer",body:"Latin inferre = to bring in, carry toward"},"wx-prefer":{src:"concept:71:words:4:ex",route:"#/word/prefer",cta:"Open the word card",title:"In a sentence · prefer",body:"Some people prefer camping to staying in hotels",clip:1},"wh-prefer":{src:"concept:71:words:4:hook",route:"#/word/prefer",cta:"Open the word card",title:"Remember it · prefer",body:"You PREFER what you put beFORE — don't mix up the R and E: pre-FER, not per-fer."},"wd-aquifer":{src:"concept:71:words:5:def",route:"#/word/aquifer",cta:"Open the word card",title:"aquifer",roman:"A-kwuh-fer",body:"underground bed or layer yielding ground water for wells and springs etc",clip:1},"wx-aquifer":{src:"concept:71:words:5:ex",route:"#/word/aquifer",cta:"Open the word card",title:"In a sentence · aquifer",body:"Farmers in the region depend on a deep underground aquifer to water their crops during dry summers.",clip:1},"wh-aquifer":{src:"concept:71:words:5:hook",route:"#/word/aquifer",cta:"Open the word card",title:"Remember it · aquifer",body:"An aquiFER FERries water underground — the FER ending means 'to carry,' like a watery chauffeur."},"wd-conifer":{src:"concept:71:words:6:def",route:"#/word/conifer",cta:"Open the word card",title:"conifer",roman:"KAH-nuh-fer",body:"any gymnospermous tree or shrub bearing cones",clip:1},"wx-conifer":{src:"concept:71:words:6:ex",route:"#/word/conifer",cta:"Open the word card",title:"In a sentence · conifer",body:"The tall conifer stood alone on the ridge, its dark green needles dusted with fresh snow.",clip:1},"wh-conifer":{src:"concept:71:words:6:hook",route:"#/word/conifer",cta:"Open the word card",title:"Remember it · conifer",body:"A conifer BEARS CONES — 'fer' means bear, so a coniFER bears cones like a pine tree."},"wd-proliferate":{src:"concept:71:words:7:def",route:"#/word/proliferate",cta:"Open the word card",title:"proliferate",roman:"proh-LIH-fer-ayt",body:"grow rapidly",clip:1},"wx-proliferate":{src:"concept:71:words:7:ex",route:"#/word/proliferate",cta:"Open the word card",title:"In a sentence · proliferate",body:"Pizza parlors proliferate in this area",clip:1},"wh-proliferate":{src:"concept:71:words:7:hook",route:"#/word/proliferate",cta:"Open the word card",title:"Remember it · proliferate",body:"To proLIFERate is to fill with LIFE rapidly — LIFE is hiding right inside proLIFErate!"},"wo-proliferate":{src:"lore:proliferate:0",route:"#/word/proliferate",cta:"Open the word card",title:"Where it comes from · proliferate",body:"Latin proles = offspring + ferre = to bear"},"wd-suffer":{src:"concept:71:words:9:def",route:"#/word/suffer",cta:"Open the word card",title:"suffer",roman:"SUH-fer",body:"undergo or be subjected to",clip:1},"wx-suffer":{src:"concept:71:words:9:ex",route:"#/word/suffer",cta:"Open the word card",title:"In a sentence · suffer",body:"He suffered the penalty",clip:1},"wh-suffer":{src:"concept:71:words:9:hook",route:"#/word/suffer",cta:"Open the word card",title:"Remember it · suffer",body:"SUFFER has a double F — two F's like two blows of pain you must bear."},"wd-offer":{src:"concept:71:words:10:def",route:"#/word/offer",cta:"Open the word card",title:"offer",roman:"AW-fer",body:"the verbal act of offering",clip:1},"wx-offer":{src:"concept:71:words:10:ex",route:"#/word/offer",cta:"Open the word card",title:"In a sentence · offer",body:"a generous offer of assistance",clip:1},"wh-offer":{src:"concept:71:words:10:hook",route:"#/word/offer",cta:"Open the word card",title:"Remember it · offer",body:"OFFER — double F in the middle; you bring something OFfer to someone, carrying it toward them."},"wd-afferent":{src:"concept:71:words:11:def",route:"#/word/afferent",cta:"Open the word card",title:"afferent",roman:"A-fer-uhnt",body:"a nerve that passes impulses from receptors toward or to the central nervous system",clip:1},"wx-afferent":{src:"concept:71:words:11:ex",route:"#/word/afferent",cta:"Open the word card",title:"In a sentence · afferent",body:"The doctor explained that afferent nerve fibers carry sensory signals from the fingertips and skin all the way inward to the brain and spinal cord for processing.",clip:1},"wh-afferent":{src:"concept:71:words:11:hook",route:"#/word/afferent",cta:"Open the word card",title:"Remember it · afferent",body:"AFFERENT carries signals inward — think 'Arriving signals': A-F-FER-ENT, double F ferrying messages to the brain."},"wo-afferent":{src:"lore:afferent:0",route:"#/word/afferent",cta:"Open the word card",title:"Where it comes from · afferent",body:"Latin afferens = bringing toward, from af+ferre = to carry"},"wd-efferent":{src:"concept:71:words:12:def",route:"#/word/efferent",cta:"Open the word card",title:"efferent",roman:"EH-fer-uhnt",body:"a nerve that conveys impulses toward or to muscles or glands",clip:1},"wx-efferent":{src:"concept:71:words:12:ex",route:"#/word/efferent",cta:"Open the word card",title:"In a sentence · efferent",body:"efferent nerves and impulses",clip:1},"wh-efferent":{src:"concept:71:words:12:hook",route:"#/word/efferent",cta:"Open the word card",title:"Remember it · efferent",body:"EFfERENT carries signals EFFERently away from the center — EFF then 'rent' the path out."},"wo-efferent":{src:"lore:efferent:0",route:"#/word/efferent",cta:"Open the word card",title:"Where it comes from · efferent",body:"Latin efferens = carrying outward (ex=out + ferre=carry)"},"wd-fertile":{src:"concept:71:words:13:def",route:"#/word/fertile",cta:"Open the word card",title:"fertile",roman:"FUR-tuhl",body:"capable of reproducing",clip:1},"wx-fertile":{src:"concept:71:words:13:ex",route:"#/word/fertile",cta:"Open the word card",title:"In a sentence · fertile",body:"The farmers were thrilled to discover that the valley soil was incredibly fertile, producing twice the expected harvest of corn and wheat in a single season.",clip:1},"wh-fertile":{src:"concept:71:words:13:hook",route:"#/word/fertile",cta:"Open the word card",title:"Remember it · fertile",body:"FERTile land BEARS fruit — fertile ends in -ILE like 'agile' and 'docile,' smooth and productive."},"wd-fertility":{src:"concept:71:words:14:def",route:"#/word/fertility",cta:"Open the word card",title:"fertility",roman:"fer-TIH-luh-tee",body:"the ratio of live births in an area to the population of that area; expressed per 1000 population per year",clip:1},"wx-fertility":{src:"concept:71:words:14:ex",route:"#/word/fertility",cta:"Open the word card",title:"In a sentence · fertility",body:"Our geography chapter compared the fertility of two countries by charting births per thousand people.",clip:1},"wh-fertility":{src:"concept:71:words:14:hook",route:"#/word/fertility",cta:"Open the word card",title:"Remember it · fertility",body:"FertilITY is the ability to bear — one L, then -ITY like ability and agility."},"wo-fertility":{src:"lore:fertility:0",route:"#/word/fertility",cta:"Open the word card",title:"Where it comes from · fertility",body:"Latin fertilitas = fruitfulness"},"wd-fertilize":{src:"concept:71:words:15:def",route:"#/word/fertilize",cta:"Open the word card",title:"fertilize",roman:"FUR-tuh-leyez",body:"provide with fertilizers or add nutrients to",clip:1},"wx-fertilize":{src:"concept:71:words:15:ex",route:"#/word/fertilize",cta:"Open the word card",title:"In a sentence · fertilize",body:"We should fertilize soil if we want to grow healthy plants",clip:1},"wh-fertilize":{src:"concept:71:words:15:hook",route:"#/word/fertilize",cta:"Open the word card",title:"Remember it · fertilize",body:"To fertilIZE is to make fertile — IZE it with American Z like a buzzing bee pollinating a flower."},"wo-fertilize":{src:"lore:fertilize:0",route:"#/word/fertilize",cta:"Open the word card",title:"Where it comes from · fertilize",body:"Latin fertilis = fruitful + -ize (to make)"},"li-u69":{src:"concept:72:concept",route:"#/stop/u69",cta:"Open this stop",title:"scrib / script (write)",body:"Latin scribere = to write. Every form of official writing — prescriptions, descriptions, scripts, manuscripts — uses this root. It appears with the full range of Latin prefixes."},"lc-u69-0":{src:"concept:72:cards:0",route:"#/stop/u69",cta:"Open this stop",title:"scrib / script (write) · The Root",body:"Latin scribere = to write. Manuscript (manus = hand + script) = written by hand. Inscription (in- + script) = written on/into a surface. Prescription (pre- + script) = written before/in advance by a doctor. Description (de- + script) = written down = an account of."},"lc-u69-1":{src:"concept:72:cards:1",route:"#/stop/u69",cta:"Open this stop",title:"scrib / script (write) · Circumscribe & Inscribe",body:"Circumscribe (circum- = around + scribe) = draw a circle around = limit the scope of. Inscribe (in- + scribe) = write on or engrave into. Subscribe (sub- + scribe) = write under = sign your name below = agree to receive."},"lc-u69-2":{src:"concept:72:cards:2",route:"#/stop/u69",cta:"Open this stop",title:"scrib / script (write) · Prescribe vs Proscribe",body:"⚠️ Prescribe (pre- + scribe) = write in advance = a doctor writes a prescription. Proscribe (pro- = put forward publicly) = publicly ban = forbid. A doctor prescribes medicine; authorities proscribe illegal activities. Two different pro-/pre- prefixes, one -scribe root."},"lc-u69-3":{src:"concept:72:cards:3",route:"#/stop/u69",cta:"Open this stop",title:"scrib / script (write) · Script in Theater & Film",body:"Script = the written text of a play or film. Postscript (post- + script) = written after = P.S. Nondescript (non- + de- + script) = not written about distinctively = lacking distinctive character = dull. Scriptural = relating to sacred writings."},"lc-u69-4":{src:"concept:72:cards:4",route:"#/stop/u69",cta:"Open this stop",title:"scrib / script (write) · Spelling scrib/script Words",body:"Root appears as -scrib- before vowels (subscribe, describe) and -script- before consonants (manuscript, inscription). Nondescript = N-O-N-D-E-S-C-R-I-P-T. Circumscribe = C-I-R-C-U-M-S-C-R-I-B-E. Conscript = C-O-N-S-C-R-I-P-T."},"uq-u69-3":{src:"unit:u69:qs:3",route:"#/stop/u69",cta:"Open this stop",title:"Whose hook?",play:{q:"“A MANU-SCRIPT was written by HAND — the SCRIPT is right there in the word!” — which word is this hook about?",opts:["manuscript","inscription","prescription","description"],after:"From “scrib / script (write)”."}},"wd-manuscript":{src:"concept:72:words:0:def",route:"#/word/manuscript",cta:"Open the word card",title:"manuscript",roman:"MA-nyuh-skrihpt",body:"the form of a literary work submitted for publication",clip:1},"wx-manuscript":{src:"concept:72:words:0:ex",route:"#/word/manuscript",cta:"Open the word card",title:"In a sentence · manuscript",body:"The ancient manuscript, written entirely by hand, had survived five hundred years in the monastery's library.",clip:1},"wh-manuscript":{src:"concept:72:words:0:hook",route:"#/word/manuscript",cta:"Open the word card",title:"Remember it · manuscript",body:"A MANU-SCRIPT was written by HAND — the SCRIPT is right there in the word!"},"wo-manuscript":{src:"lore:manuscript:0",route:"#/word/manuscript",cta:"Open the word card",title:"Where it comes from · manuscript",body:"Latin manus = hand + scribere = to write"},"wd-inscription":{src:"concept:72:words:1:def",route:"#/word/inscription",cta:"Open the word card",title:"inscription",roman:"ih-n-s-k-r-IH-p-sh-uh-n",body:"text that is written or otherwise marked upon an object so as to create a lasting or public record",clip:1},"wx-inscription":{src:"concept:72:words:1:ex",route:"#/word/inscription",cta:"Open the word card",title:"In a sentence · inscription",body:"The archaeologist carefully brushed away the dust to reveal the ancient inscription carved into the stone wall.",clip:1},"wh-inscription":{src:"concept:72:words:1:hook",route:"#/word/inscription",cta:"Open the word card",title:"Remember it · inscription",body:"An inSCRIPTion is like a SCRIPT carved in stone — drop the E from scribe and add -TION."},"wo-inscription":{src:"lore:inscription:0",route:"#/word/inscription",cta:"Open the word card",title:"Where it comes from · inscription",body:"Latin inscribere = to write upon"},"wd-prescription":{src:"concept:72:words:2:def",route:"#/word/prescription",cta:"Open the word card",title:"prescription",roman:"pruh-SKRIH-pshuhn",body:"directions prescribed beforehand; the action of prescribing authoritative rules or directions",clip:1},"wx-prescription":{src:"concept:72:words:2:ex",route:"#/word/prescription",cta:"Open the word card",title:"In a sentence · prescription",body:"I tried to follow her prescription for success",clip:1},"wh-prescription":{src:"concept:72:words:2:hook",route:"#/word/prescription",cta:"Open the word card",title:"Remember it · prescription",body:"Don't PERvert the spelling — it's PRE not PER: PRE-SCRIP-TION, written before you're sick."},"wo-prescription":{src:"lore:prescription:0",route:"#/word/prescription",cta:"Open the word card",title:"Where it comes from · prescription",body:"Latin praescriptio = order written beforehand"},"wd-description":{src:"concept:72:words:3:def",route:"#/word/description",cta:"Open the word card",title:"description",roman:"dih-SKRIH-pshuhn",body:"a statement that represents something in words",clip:1},"wx-description":{src:"concept:72:words:3:ex",route:"#/word/description",cta:"Open the word card",title:"In a sentence · description",body:"every description of book was there",clip:1},"wh-description":{src:"concept:72:words:3:hook",route:"#/word/description",cta:"Open the word card",title:"Remember it · description",body:"A deSCRIPTion is a SCRIPT written about something — find SCRIPT hiding inside."},"wo-description":{src:"lore:description:0",route:"#/word/description",cta:"Open the word card",title:"Where it comes from · description",body:"Latin describere = to write down"},"wd-transcription":{src:"concept:72:words:4:def",route:"#/word/transcription",cta:"Open the word card",title:"transcription",roman:"tra-NSKRIH-pshuhn",body:"something written, especially copied from one medium to another, as a typewritten version of dictation",clip:1},"wx-transcription":{src:"concept:72:words:4:ex",route:"#/word/transcription",cta:"Open the word card",title:"In a sentence · transcription",body:"The court reporter's transcription of the entire three-hour trial filled more than two hundred pages.",clip:1},"wh-transcription":{src:"concept:72:words:4:hook",route:"#/word/transcription",cta:"Open the word card",title:"Remember it · transcription",body:"TRANS(fer) + SCRIPT: transferring what was scripted (written)"},"wo-transcription":{src:"lore:transcription:0",route:"#/word/transcription",cta:"Open the word card",title:"Where it comes from · transcription",body:"Latin transcribere = to copy over (trans=across + scribere=write)"},"wd-circumscribe":{src:"concept:72:words:5:def",route:"#/word/circumscribe",cta:"Open the word card",title:"circumscribe",roman:"sur-kuh-MSKREYEB",body:"draw a line around",clip:1},"wx-circumscribe":{src:"concept:72:words:5:ex",route:"#/word/circumscribe",cta:"Open the word card",title:"In a sentence · circumscribe",body:"The teacher used a compass to circumscribe a perfect circle around the triangle on the chalkboard.",clip:1},"wh-circumscribe":{src:"concept:72:words:5:hook",route:"#/word/circumscribe",cta:"Open the word card",title:"Remember it · circumscribe",body:"CIRCUM means around + SCRIBE means write — to write a circle around something"},"wo-circumscribe":{src:"lore:circumscribe:0",route:"#/word/circumscribe",cta:"Open the word card",title:"Where it comes from · circumscribe",body:"Latin circum (around) + scribere (to write/draw)"},"wd-inscribe":{src:"concept:72:words:6:def",route:"#/word/inscribe",cta:"Open the word card",title:"inscribe",roman:"ih-NSKREYEB",body:"carve, cut, or etch into a material or surface",clip:1},"wx-inscribe":{src:"concept:72:words:6:ex",route:"#/word/inscribe",cta:"Open the word card",title:"In a sentence · inscribe",body:"The jeweler offered to inscribe a heartfelt message along the inner band of the ring, so the couple would always carry those meaningful words with them wherever they traveled.",clip:1},"wh-inscribe":{src:"concept:72:words:6:hook",route:"#/word/inscribe",cta:"Open the word card",title:"Remember it · inscribe",body:"To INSCRIBE is to write IN — a SCRIBE writes IN to stone, starts with IN not EN."},"wd-subscribe":{src:"concept:72:words:7:def",route:"#/word/subscribe",cta:"Open the word card",title:"subscribe",roman:"suh-BSKREYEB",body:"offer to buy, as of stocks and shares",clip:1},"wx-subscribe":{src:"concept:72:words:7:ex",route:"#/word/subscribe",cta:"Open the word card",title:"In a sentence · subscribe",body:"The broker subscribed 500 shares",clip:1},"wh-subscribe":{src:"concept:72:words:7:hook",route:"#/word/subscribe",cta:"Open the word card",title:"Remember it · subscribe",body:"To subSCRIBE is to write your name UNDER a publication — a SCRIBE signs below."},"wd-conscript":{src:"concept:72:words:8:def",route:"#/word/conscript",cta:"Open the word card",title:"conscript",roman:"KAH-nskrihpt",body:"someone who is drafted into military service",clip:1},"wx-conscript":{src:"concept:72:words:8:ex",route:"#/word/conscript",cta:"Open the word card",title:"In a sentence · conscript",body:"The men were conscripted",clip:1},"wh-conscript":{src:"concept:72:words:8:hook",route:"#/word/conscript",cta:"Open the word card",title:"Remember it · conscript",body:"A conSCRIPT is literally WRITTEN into military service — the script is the enlistment paper."},"wd-postscript":{src:"concept:72:words:11:def",route:"#/word/postscript",cta:"Open the word card",title:"postscript",roman:"POH-skrihpt",body:"a note appended to a letter after the signature",clip:1},"wx-postscript":{src:"concept:72:words:11:ex",route:"#/word/postscript",cta:"Open the word card",title:"In a sentence · postscript",body:"In the postscript of her letter, she added a quick note reminding him to feed the cat.",clip:1},"wh-postscript":{src:"concept:72:words:11:hook",route:"#/word/postscript",cta:"Open the word card",title:"Remember it · postscript",body:"A POSTSCRIPT is written (SCRIPT) after (POST) — don't forget the S in SCRIPT."},"wo-postscript":{src:"lore:postscript:0",route:"#/word/postscript",cta:"Open the word card",title:"Where it comes from · postscript",body:"Latin scriptum = written"},"wd-nondescript":{src:"concept:72:words:12:def",route:"#/word/nondescript",cta:"Open the word card",title:"nondescript",roman:"n-AH-n-d-ih-s-k-r-IH-p-t",body:"lacking distinguishing characteristics or a distinctive character",clip:1},"wx-nondescript":{src:"concept:72:words:12:ex",route:"#/word/nondescript",cta:"Open the word card",title:"In a sentence · nondescript",body:"women dressed in nondescript clothes",clip:1},"wh-nondescript":{src:"concept:72:words:12:hook",route:"#/word/nondescript",cta:"Open the word card",title:"Remember it · nondescript",body:"NONDESCRIPT has 'de' not 'di' — something nondescript is DE-void of description."},"wo-nondescript":{src:"lore:nondescript:0",route:"#/word/nondescript",cta:"Open the word card",title:"Where it comes from · nondescript",body:"Latin non = not + descriptus = described"},"wd-scriptural":{src:"concept:72:words:13:def",route:"#/word/scriptural",cta:"Open the word card",title:"scriptural",roman:"SKRIH-pcher-uhl",body:"of or pertaining to or contained in or in accordance with the Bible",clip:1},"wx-scriptural":{src:"concept:72:words:13:ex",route:"#/word/scriptural",cta:"Open the word card",title:"In a sentence · scriptural",body:"The minister's sermon was filled with scriptural references, quoting passages from the Bible to support each point and helping the congregation connect ancient teachings to everyday modern life.",clip:1},"wh-scriptural":{src:"concept:72:words:13:hook",route:"#/word/scriptural",cta:"Open the word card",title:"Remember it · scriptural",body:"SCRIPTURAL contains SCRIPT+URE+AL — holy writing wrapped in three layers of meaning."},"wo-scriptural":{src:"lore:scriptural:0",route:"#/word/scriptural",cta:"Open the word card",title:"Where it comes from · scriptural",body:"Latin scriptura = sacred writing"},"wd-ascribe":{src:"concept:72:words:14:def",route:"#/word/ascribe",cta:"Open the word card",title:"ascribe",roman:"uh-SKREYEB",body:"attribute or credit to",clip:1},"wx-ascribe":{src:"concept:72:words:14:ex",route:"#/word/ascribe",cta:"Open the word card",title:"In a sentence · ascribe",body:"Many people ascribe the invention of the telephone to Alexander Graham Bell, though others believe different inventors deserve credit.",clip:1},"wh-ascribe":{src:"concept:72:words:14:hook",route:"#/word/ascribe",cta:"Open the word card",title:"Remember it · ascribe",body:"aSCRIBE — a SCRIBE writes who deserves credit"},"wo-ascribe":{src:"lore:ascribe:0",route:"#/word/ascribe",cta:"Open the word card",title:"Where it comes from · ascribe",body:"Latin 'ascribere' = to enroll/add in writing, from 'ad-' = to + 'scribere' = to write"},"li-u70":{src:"concept:73:concept",route:"#/stop/u70",cta:"Open this stop",title:"port (carry)",body:"Latin portare = to carry. One of the clearest-meaning roots in English — every port- word involves carrying, moving, or transporting something, physically or metaphorically."},"lc-u70-0":{src:"concept:73:cards:0",route:"#/stop/u70",cta:"Open this stop",title:"port (carry) · The Root",body:"Latin portare = to carry. Import (in- = in + port) = carry in from another country. Export (ex- = out) = carry out to another country. Transport (trans- = across) = carry across. Report (re- = back) = carry back (news). Support (sub- = under) = carry from under = hold up."},"lc-u70-1":{src:"concept:73:cards:1",route:"#/stop/u70",cta:"Open this stop",title:"port (carry) · Portfolio & Portmanteau",body:"Portfolio (port- + foglio = leaf/sheet) = something that carries papers/documents. Portmanteau (port- + manteau = cloak) = a large suitcase that carries cloaks. Also (Lewis Carroll): a portmanteau word = a word that carries two words inside it (smog = smoke + fog)."},"lc-u70-2":{src:"concept:73:cards:2",route:"#/stop/u70",cta:"Open this stop",title:"port (carry) · Deportment & Comport",body:"Deportment (de- + port- + -ment) = the way one carries oneself = bearing, posture, manner. Comport (com- = together) = carry together = behave in a certain way. Comportment = behavior and bearing. Disport (dis- = away) = carry oneself away in play = amuse oneself."},"lc-u70-3":{src:"concept:73:cards:3",route:"#/stop/u70",cta:"Open this stop",title:"port (carry) · Rapport — the Hidden port",body:"Rapport (re- + French apporter = bring back + port) = carrying feeling back = a sympathetic relationship. The -ort at the end shows the port- root through French. Rapport = R-A-P-P-O-R-T (double-p from French assimilation). A frequently misspelled word because the port root is not obvious."},"lc-u70-4":{src:"concept:73:cards:4",route:"#/stop/u70",cta:"Open this stop",title:"port (carry) · Spelling port- Words",body:"Transport = T-R-A-N-S-P-O-R-T. Deportment = D-E-P-O-R-T-M-E-N-T. Rapport = R-A-P-P-O-R-T (double-p, silent final t!). Portfolio = P-O-R-T-F-O-L-I-O. Portmanteau = P-O-R-T-M-A-N-T-E-A-U (the -eau French ending after the Latin port-). Root + French ending in one word."},"uq-u70-3":{src:"unit:u70:qs:3",route:"#/stop/u70",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁ — goods come IN through a PORT; IM replaces IN before 'p,' like goods docking at the harbor.” — which word is this hook about?",opts:["import","export","transport","report"],after:"From “port (carry)”."}},"wd-import":{src:"concept:73:words:0:def",route:"#/word/import",cta:"Open the word card",title:"import",roman:"ih-MPAWRT",body:"commodities (goods or services) bought from a foreign country",clip:1},"wx-import":{src:"concept:73:words:0:ex",route:"#/word/import",cta:"Open the word card",title:"In a sentence · import",body:"the lead role was played by an import from Sweden",clip:1},"wh-import":{src:"concept:73:words:0:hook",route:"#/word/import",cta:"Open the word card",title:"Remember it · import",body:"IMPORT — goods come IN through a PORT; IM replaces IN before 'p,' like goods docking at the harbor."},"wd-export":{src:"concept:73:words:1:def",route:"#/word/export",cta:"Open the word card",title:"export",roman:"EH-kspawrt",body:"commodities (goods or services) sold to a foreign country",clip:1},"wx-export":{src:"concept:73:words:1:ex",route:"#/word/export",cta:"Open the word card",title:"In a sentence · export",body:"we export less than we import and have a negative trade balance",clip:1},"wh-export":{src:"concept:73:words:1:hook",route:"#/word/export",cta:"Open the word card",title:"Remember it · export",body:"To EXport is to EXIT through the PORT with your goods."},"wd-transport":{src:"concept:73:words:2:def",route:"#/word/transport",cta:"Open the word card",title:"transport",roman:"tra-NSPAWRT",body:"something that serves as a means of transportation",clip:1},"wx-transport":{src:"concept:73:words:2:ex",route:"#/word/transport",cta:"Open the word card",title:"In a sentence · transport",body:"In that mountain village, a donkey cart is the only transport for heavy sacks of grain.",clip:1},"wh-transport":{src:"concept:73:words:2:hook",route:"#/word/transport",cta:"Open the word card",title:"Remember it · transport",body:"A PORT is where ships carry cargo — transPORT carries things across."},"wd-report":{src:"concept:73:words:3:def",route:"#/word/report",cta:"Open the word card",title:"report",roman:"ree-PAWRT",body:"a written document describing the findings of some individual or group",clip:1},"wx-report":{src:"concept:73:words:3:ex",route:"#/word/report",cta:"Open the word card",title:"In a sentence · report",body:"Priya handed in a six-page report on the tadpoles she raised in class.",clip:1},"wh-report":{src:"concept:73:words:3:hook",route:"#/word/report",cta:"Open the word card",title:"Remember it · report",body:"A reporter CARRIES news BACK to you — re+PORT like a porter carrying luggage back."},"wd-support":{src:"concept:73:words:4:def",route:"#/word/support",cta:"Open the word card",title:"support",roman:"suh-PAWRT",body:"the activity of providing for or maintaining by supplying with money or necessities",clip:1},"wx-support":{src:"concept:73:words:4:ex",route:"#/word/support",cta:"Open the word card",title:"In a sentence · support",body:"his support kept the family together",clip:1},"wh-support":{src:"concept:73:words:4:hook",route:"#/word/support",cta:"Open the word card",title:"Remember it · support",body:"A SUPPORTer carries you from under — like a PORT-er who lifts from below (SUB)."},"wd-portfolio":{src:"concept:73:words:5:def",route:"#/word/portfolio",cta:"Open the word card",title:"portfolio",roman:"paw-RTFOH-lee-oh",body:"a large, flat, thin case for carrying loose papers or drawings or maps; usually leather",clip:1},"wx-portfolio":{src:"concept:73:words:5:ex",route:"#/word/portfolio",cta:"Open the word card",title:"In a sentence · portfolio",body:"he remembered her because she was carrying a large portfolio",clip:1},"wh-portfolio":{src:"concept:73:words:5:hook",route:"#/word/portfolio",cta:"Open the word card",title:"Remember it · portfolio",body:"A portFOLIO carries your FOLIOs — sheets of paper you PORTA (carry) around to show your work."},"wo-portfolio":{src:"lore:portfolio:0",route:"#/word/portfolio",cta:"Open the word card",title:"Where it comes from · portfolio",body:"Italian portafoglio; portare(carry)+foglio(sheet/leaf)"},"wd-portmanteau":{src:"concept:73:words:6:def",route:"#/word/portmanteau",cta:"Open the word card",title:"portmanteau",roman:"PAW-rtmah-ntoh",body:"a new word formed by joining two others and combining their meanings",clip:1},"wx-portmanteau":{src:"concept:73:words:6:ex",route:"#/word/portmanteau",cta:"Open the word card",title:"In a sentence · portmanteau",body:"Lewis Carroll was a master of the portmanteau, blending 'smoke' and 'fog' into the word 'smog.'",clip:1},"wh-portmanteau":{src:"concept:73:words:6:hook",route:"#/word/portmanteau",cta:"Open the word card",title:"Remember it · portmanteau",body:"A portmanteau CARRIES two words like a bag carries two halves"},"wo-portmanteau":{src:"lore:portmanteau:0",route:"#/word/portmanteau",cta:"Open the word card",title:"Where it comes from · portmanteau",body:"French porter (to carry) + manteau (cloak)"},"wd-deportment":{src:"concept:73:words:7:def",route:"#/word/deportment",cta:"Open the word card",title:"deportment",roman:"duh-PAW-rtmuhnt",body:"the manner in which a person behaves toward others; conduct and bearing",clip:1},"wx-deportment":{src:"concept:73:words:7:ex",route:"#/word/deportment",cta:"Open the word card",title:"In a sentence · deportment",body:"The finishing school emphasized deportment, teaching students to walk with confidence and speak with courtesy.",clip:1},"wh-deportment":{src:"concept:73:words:7:hook",route:"#/word/deportment",cta:"Open the word card",title:"Remember it · deportment",body:"dePORTment is about how you PORT or carry yourself in public"},"wo-deportment":{src:"lore:deportment:0",route:"#/word/deportment",cta:"Open the word card",title:"Where it comes from · deportment",body:"French déporter = to conduct oneself, from Latin deportare = to carry away"},"wd-comport":{src:"concept:73:words:8:def",route:"#/word/comport",cta:"Open the word card",title:"comport",roman:"kuh-MPAWRT",body:"behave well or properly",clip:1},"wx-comport":{src:"concept:73:words:8:ex",route:"#/word/comport",cta:"Open the word card",title:"In a sentence · comport",body:"Visitors must comport themselves quietly inside the ancient library, the guide reminded us.",clip:1},"wh-comport":{src:"concept:73:words:8:hook",route:"#/word/comport",cta:"Open the word card",title:"Remember it · comport",body:"Comport yourself well — carry yourself together: 'port' like a porter who carries things with dignity."},"wd-rapport":{src:"concept:73:words:9:def",route:"#/word/rapport",cta:"Open the word card",title:"rapport",roman:"r-a-p-AW-r",body:"relation or connection",clip:1},"wx-rapport":{src:"concept:73:words:9:ex",route:"#/word/rapport",cta:"Open the word card",title:"In a sentence · rapport",body:"The teacher quickly built a warm rapport with her students by listening to their ideas.",clip:1},"wh-rapport":{src:"concept:73:words:9:hook",route:"#/word/rapport",cta:"Open the word card",title:"Remember it · rapport",body:"Good RAPPORT carries a silent T at the end — like a French diplomat, elegantly quiet: R-A-P-P-O-R-T."},"wo-rapport":{src:"lore:rapport:0",route:"#/word/rapport",cta:"Open the word card",title:"Where it comes from · rapport",body:"French rapporter = to bring back, relate"},"wd-disport":{src:"concept:73:words:10:def",route:"#/word/disport",cta:"Open the word card",title:"disport",roman:"dis-PORT",body:"occupy in an agreeable, entertaining or pleasant fashion",clip:1},"wx-disport":{src:"concept:73:words:10:ex",route:"#/word/disport",cta:"Open the word card",title:"In a sentence · disport",body:"The children disport themselves gleefully at the beach, splashing and chasing waves all afternoon.",clip:1},"wh-disport":{src:"concept:73:words:10:hook",route:"#/word/disport",cta:"Open the word card",title:"Remember it · disport",body:"To disport is to carry yourself away for fun — think of a PORT where ships escape to play."},"wd-portable":{src:"concept:73:words:11:def",route:"#/word/portable",cta:"Open the word card",title:"portable",roman:"PAW-rtuh-buhl",body:"a small light typewriter; usually with a case in which it can be carried",clip:1},"wx-portable":{src:"concept:73:words:11:ex",route:"#/word/portable",cta:"Open the word card",title:"In a sentence · portable",body:"a portable television set",clip:1},"wh-portable":{src:"concept:73:words:11:hook",route:"#/word/portable",cta:"Open the word card",title:"Remember it · portable",body:"PORTABLE contains PORT — you can carry it to any PORT in the world; remember -able not -ible."},"wo-portable":{src:"lore:portable:0",route:"#/word/portable",cta:"Open the word card",title:"Where it comes from · portable",body:"Latin portare = to carry"},"wd-porter":{src:"concept:73:words:12:def",route:"#/word/porter",cta:"Open the word card",title:"porter",roman:"PAW-rter",body:"a person employed to carry luggage and supplies",clip:1},"wx-porter":{src:"concept:73:words:12:ex",route:"#/word/porter",cta:"Open the word card",title:"In a sentence · porter",body:"The helpful porter loaded all five suitcases onto his cart and led us swiftly to our hotel room.",clip:1},"wh-porter":{src:"concept:73:words:12:hook",route:"#/word/porter",cta:"Open the word card",title:"Remember it · porter",body:"A PORTER carries your bags at the PORT — the -ER at the end means he's the one doing the carrying."},"wd-importation":{src:"concept:73:words:13:def",route:"#/word/importation",cta:"Open the word card",title:"importation",roman:"ih-mpaw-RTAY-shuhn",body:"the commercial activity of buying and bringing in goods from a foreign country",clip:1},"wx-importation":{src:"concept:73:words:13:ex",route:"#/word/importation",cta:"Open the word card",title:"In a sentence · importation",body:"The new trade policy restricted the importation of foreign steel to protect jobs in the domestic manufacturing industry.",clip:1},"wh-importation":{src:"concept:73:words:13:hook",route:"#/word/importation",cta:"Open the word card",title:"Remember it · importation",body:"IMPORTATION — a NATION that does IMPORTATION brings goods IN through its ports; -ATION seals the deal."},"wo-importation":{src:"lore:importation:0",route:"#/word/importation",cta:"Open the word card",title:"Where it comes from · importation",body:"Latin importare = to bring in"},"li-u71":{src:"concept:74:concept",route:"#/stop/u71",cta:"Open this stop",title:"miss / mit (send)",body:"Latin mittere = to send. It appears as -miss- in nouns and -mit in verbs — the same root, two faces. From mission to remit, dismiss to submit, sending is this root's business."},"lc-u71-0":{src:"concept:74:cards:0",route:"#/stop/u71",cta:"Open this stop",title:"miss / mit (send) · The Root",body:"Latin mittere = to send. Transmit (trans- = across) = send across. Omit (ob- = away) = send away = leave out. Emit (e- = out) = send out. Remit (re- = back) = send back (money). Submit (sub- = under) = send oneself under the authority of. Verb form = -mit."},"lc-u71-1":{src:"concept:74:cards:1",route:"#/stop/u71",cta:"Open this stop",title:"miss / mit (send) · -mission = The Noun Form",body:"mittere → missio (noun). Permission (per- + mission) = sending through = official allowance. Intermission = a sending between acts = a break. Missionary = one sent on a mission. Emission = something sent out. Commission (com- + mission) = sent together = an official duty."},"lc-u71-2":{src:"concept:74:cards:2",route:"#/stop/u71",cta:"Open this stop",title:"miss / mit (send) · Missile & Message",body:'Missile = missilis = something sent = a projectile. Message = missaticum = something sent = communication. Messenger = the person who sends/carries the message. All from mittere. Missive = a formal written message that is "sent."'},"lc-u71-3":{src:"concept:74:cards:3",route:"#/stop/u71",cta:"Open this stop",title:"miss / mit (send) · Dismiss & Remissive",body:"Dismiss (dis- + miss) = send apart = discharge. Remissive (re- + miss) = sending back = forgiving. Irremissible = cannot be sent away = unforgivable. Commissar = com- + miss- = official sent with a commission. Demise (de- + mise) = sent down = the end/death of something."},"lc-u71-4":{src:"concept:74:cards:4",route:"#/stop/u71",cta:"Open this stop",title:"miss / mit (send) · Spelling -miss-/-mit-",body:"The verb always uses -mit: commit, submit, transmit, permit, admit. The noun always uses -mission or -missive: commission, permission, submission, admission. When -mit is stressed before -ing/-ed/-er, double the t: commit → committed, transmit → transmitting, permit → permitted."},"uq-u71-3":{src:"unit:u71:qs:3",route:"#/stop/u71",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁ sends just one T when you MITt the signal — only double T when adding suffixes.” — which word is this hook about?",opts:["transmit","omit","emit","remit"],after:"From “miss / mit (send)”."}},"wd-transmit":{src:"concept:74:words:0:def",route:"#/word/transmit",cta:"Open the word card",title:"transmit",roman:"tra-NZMIHT",body:"transfer to another",clip:1},"wx-transmit":{src:"concept:74:words:0:ex",route:"#/word/transmit",cta:"Open the word card",title:"In a sentence · transmit",body:"Bees transmit pollen from flower to flower as they hunt for sweet nectar.",clip:1},"wh-transmit":{src:"concept:74:words:0:hook",route:"#/word/transmit",cta:"Open the word card",title:"Remember it · transmit",body:"transMIT sends just one T when you MITt the signal — only double T when adding suffixes."},"wd-omit":{src:"concept:74:words:1:def",route:"#/word/omit",cta:"Open the word card",title:"omit",roman:"oh-MIHT",body:"prevent from being included or considered or accepted",clip:1},"wx-omit":{src:"concept:74:words:1:ex",route:"#/word/omit",cta:"Open the word card",title:"In a sentence · omit",body:"Never omit your surname on the entry form, or the judges cannot find you.",clip:1},"wh-omit":{src:"concept:74:words:1:hook",route:"#/word/omit",cta:"Open the word card",title:"Remember it · omit",body:"OMIT has just ONE 'm' — don't add an extra letter to a word that means to leave things out!"},"wd-emit":{src:"concept:74:words:2:def",route:"#/word/emit",cta:"Open the word card",title:"emit",roman:"ih-MIHT",body:"expel (gases or odors)",clip:1},"wx-emit":{src:"concept:74:words:2:ex",route:"#/word/emit",cta:"Open the word card",title:"In a sentence · emit",body:"The ozone layer blocks some harmful rays which the sun emits",clip:1},"wh-emit":{src:"concept:74:words:2:hook",route:"#/word/emit",cta:"Open the word card",title:"Remember it · emit",body:"To EMIT is to let it OUT — one m, like one exit door."},"wo-emit":{src:"lore:emit:0",route:"#/word/emit",cta:"Open the word card",title:"Where it comes from · emit",body:"Latin e- (out) + mittere (to send) — to send out."},"wd-remit":{src:"concept:74:words:3:def",route:"#/word/remit",cta:"Open the word card",title:"remit",roman:"ree-MIHT",body:"the topic that a person, committee, or piece of research is expected to deal with or has authority to deal with",clip:1},"wx-remit":{src:"concept:74:words:3:ex",route:"#/word/remit",cta:"Open the word card",title:"In a sentence · remit",body:"they set up a group with a remit to suggest ways for strengthening family life",clip:1},"wh-remit":{src:"concept:74:words:3:hook",route:"#/word/remit",cta:"Open the word card",title:"Remember it · remit",body:"reMIT has one M — you send (MIT) something back RE-once, not twice."},"wd-submit":{src:"concept:74:words:4:def",route:"#/word/submit",cta:"Open the word card",title:"submit",roman:"suh-BMIHT",body:"refer for judgment or consideration",clip:1},"wx-submit":{src:"concept:74:words:4:ex",route:"#/word/submit",cta:"Open the word card",title:"In a sentence · submit",body:"The lawyers submitted the material to the court",clip:1},"wh-submit":{src:"concept:74:words:4:hook",route:"#/word/submit",cta:"Open the word card",title:"Remember it · submit",body:"subMIT: you SEND IT under the judge's authority."},"wo-submit":{src:"lore:submit:0",route:"#/word/submit",cta:"Open the word card",title:"Where it comes from · submit",body:"Latin sub- 'under' + mittere 'to send' — to send under someone's judgment."},"wd-permission":{src:"concept:74:words:5:def",route:"#/word/permission",cta:"Open the word card",title:"permission",roman:"per-MIH-shuhn",body:"approval to do something",clip:1},"wx-permission":{src:"concept:74:words:5:ex",route:"#/word/permission",cta:"Open the word card",title:"In a sentence · permission",body:"Before leaving campus for the field trip, every student had to have a signed permission slip from a parent.",clip:1}});
